import json,re
from collections import Counter
s=json.load(open('cistrome_samples.json'))
for files in [['borzoi_targets_human.txt'],['borzoi_targets_mouse.txt'],['borzoi_targets_human.txt','borzoi_targets_mouse.txt']]:
 enc=set(); gsm=set(); by=Counter()
 for fn in files:
  with open(fn) as f:
   h=f.readline().rstrip().split('\\t')
   for l in f:
    x=dict(zip(h,l.rstrip().split('\\t')))
    for q in re.findall(r'ENCSR[A-Z0-9]+',x['file']+' '+x['identifier']): enc.add(q)
    for q in re.findall(r'GSM\\d+',x['file']+' '+x['identifier']): gsm.add(q)
 m=[]
 for x in s.values():
  eid=x['external_id']; norm=re.sub(r'_\\d+"'$'"','',eid)
  if norm in enc or eid in gsm: m.append(x)
 print(files,'enc',len(enc),'gsm',len(gsm),'matches',len(m),'by type',Counter(x['external_id_type'] for x in m),'species',Counter(x['species'] for x in m))
 print('mouse cistrome matches',[(x['id'],x['external_id']) for x in m if x['species']=='mus_musculus'])
